// This guide explains options; actual cards and life are changed on the table.
const hhState={hand:{},hp:'',max:'',alive:players,character:'',usedBang:false,weapon:'colt',equipped:new Set(),tab:'전체'};
const hhCategories={bang:'공격',mancato:'방어',birra:'회복',barile:'장비',prigione:'방해',dinamite:'장비',mustang:'장비',mirino:'장비',panico:'방해',catbalou:'방해',duello:'공격',indiani:'공격',gatling:'공격',saloon:'회복',emporio:'뽑기',diligenza:'뽑기',wellsfargo:'뽑기',volcanic:'장비',schofield:'장비',remington:'장비',carabine:'장비',winchester:'장비'};
const hhPlayable=()=>cards.filter(c=>hhCategories[c.id]);
const hhCount=id=>hhState.hand[id]||0;
const hhTotal=()=>Object.values(hhState.hand).reduce((a,b)=>a+b,0);
const hhCard=id=>cards.find(c=>c.id===id);
function hhPicker(){return hhPlayable().filter(c=>hhState.tab==='전체'||hhCategories[c.id]===hhState.tab).map(c=>`<div class="hh-pick ${hhCount(c.id)?'chosen':''}"><button type="button" class="hh-pick-card" data-hh-plus="${c.id}" aria-label="${c.name} 한 장 추가">${img(c.id)}<b>${c.name}</b></button><div class="hh-quantity"><button data-hh-minus="${c.id}" aria-label="${c.name} 한 장 빼기" ${hhCount(c.id)?'':'disabled'}>−</button><span aria-label="선택한 수량">${hhCount(c.id)}장</span><button data-hh-plus="${c.id}" aria-label="${c.name} 한 장 더하기">+</button></div></div>`).join('')}
function hhOpen(){openModal(`<section class="hand-helper"><h2>손에 든 카드, 이렇게 써요.</h2><p class="hh-lead">먼저 <strong>2장을 뽑은 뒤, 지금 손에 든 카드</strong>를 골라주세요. 그림을 누를 때마다 1장씩 추가돼요.</p><p class="hh-private"><strong>손의 카드가 다른 사람에게 보이지 않게 확인하세요.</strong></p><div class="hh-tabs">${['전체','공격','회복','장비','뽑기','방해','방어'].map(t=>`<button data-hh-tab="${t}" aria-pressed="${hhState.tab===t}" class="${hhState.tab===t?'on':''}">${t}</button>`).join('')}</div><div class="hh-picker" id="hh-picker">${hhPicker()}</div><div class="hh-selected" id="hh-selected"></div><details class="hh-context" ${hhState.hp||hhState.character?'open':''}><summary>내 상황도 알려주면 더 정확해요</summary><div class="hh-life-inputs"><label>현재 생명<select id="hh-hp"><option value="">모르겠어요</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${hhState.hp===String(n)?'selected':''}>${n}</option>`).join('')}</select></label><label>최대 생명<select id="hh-max"><option value="">모르겠어요</option>${[3,4,5].map(n=>`<option value="${n}" ${hhState.max===String(n)?'selected':''}>${n}</option>`).join('')}</select></label></div><label class="hh-field">게임에 남은 사람 수<select id="hh-alive">${[2,3,4,5,6,7].map(n=>`<option value="${n}" ${hhState.alive===n?'selected':''}>${n}명</option>`).join('')}</select></label><label class="hh-field">내 캐릭터<select id="hh-character"><option value="">선택하지 않음</option>${chars.map(([id,ko])=>`<option value="${id}" ${hhState.character===id?'selected':''}>${ko}</option>`).join('')}</select></label><label class="hh-field">이미 내 앞에 놓은 무기<select id="hh-weapon">${calcWeapons.map(([id,name,r])=>`<option value="${id}" ${hhState.weapon===id?'selected':''}>${name} · 사거리 ${r}</option>`).join('')}</select></label><label class="hh-check"><span>이번 차례에 뱅!을 이미 썼어요</span><input type="checkbox" id="hh-used-bang" ${hhState.usedBang?'checked':''}></label><div class="hh-equipped"><span>이미 내 앞에 놓인 장비</span>${['barile','mustang','mirino','dinamite'].map(id=>`<label><input type="checkbox" data-hh-equipped="${id}" ${hhState.equipped.has(id)?'checked':''}>${names[id]}</label>`).join('')}</div></details><button type="button" class="btn hh-explain" id="hh-explain">선택한 카드 사용법 보기 →</button></section>`);hhSelected();}
function hhSelected(){const selected=hhPlayable().filter(c=>hhCount(c.id));$('#hh-selected').innerHTML=selected.length?`<b>선택 ${hhTotal()}장</b><p>${selected.map(c=>`${c.name} ${hhCount(c.id)}장`).join(' · ')}</p>`:'그림으로 손의 카드를 골라주세요.';$('#hh-explain').disabled=!selected.length;}
function hhRule(id){const c=hhCard(id);return `<details class="hh-card-rule"><summary>${c.name} 자세히</summary><p>${c.text}</p>${c.note?`<p class="callout">${c.note}</p>`:''}</details>`}
function hhOption(id,status,body){return `<article class="hh-option">${img(id)}<div><h4>${names[id]} <small>${hhCount(id)}장</small></h4><span class="hh-status">${status}</span><p>${body}</p>${hhRule(id)}</div></article>`}
function hhResults(){
 const h=hhState,selected=hhPlayable().filter(c=>hhCount(c.id));if(!selected.length){hhOpen();return}
 const hp=h.hp?Number(h.hp):null,max=h.max?Number(h.max):null,full=hp!==null&&max!==null&&hp>=max;
 if(hp!==null&&max!==null&&hp>max){hhOpen();$('#hh-selected').innerHTML='<strong>현재 생명이 최대 생명보다 커요. 생명 수를 다시 확인하세요.</strong>';return}
 const char=hhCard(h.character),unlimited=h.character==='willythekid'||h.weapon==='volcanic',canEquipVolcanic=hhCount('volcanic')>0&&h.weapon!=='volcanic',janet=h.character==='calamityjanet';
 const groups={'카드를 더 가져오기':[],'회복하기':[],'장비 놓기':[],'공격하기':[],'다른 사람 방해하기':[],'공격받을 때 남겨두기':[]};
 const sequence=[];
 for(const id of ['diligenza','wellsfargo','emporio'])if(hhCount(id)){groups['카드를 더 가져오기'].push(hhOption(id,'내 차례에 사용',id==='emporio'?'남은 사람 수만큼 카드를 공개하고, 나부터 시계 방향으로 하나씩 골라요. 사용한 잡화점은 버려요.':`이 카드를 쓰고 버리면 뽑는 더미에서 ${id==='diligenza'?2:3}장을 가져와요. 새로 뽑은 카드도 이번 차례에 쓸 수 있어요.`));}
 if(hhCount('diligenza')||hhCount('wellsfargo')||hhCount('emporio'))sequence.push('카드를 더 뽑는 카드를 먼저 쓰면 선택지가 늘어요. 새로 받은 카드도 확인하세요.');
 if(hhCount('birra')){const status=h.alive===2?'지금은 효과 없음':full?'내 생명은 이미 최대':hp===null||max===null?'현재·최대 생명 확인':'내 생명 회복 가능';const body=h.alive===2?'<strong>2명만 남으면 맥주는 생명을 회복시키지 못해요.</strong>':full?'시작할 때의 최대 생명을 넘길 수 없어요. 나중에 생명을 잃었을 때를 위해 남겨둘 수 있어요.':'내 차례에 1장 쓰고 버리면 내 생명 1을 회복해요. 최대 생명까지만 회복하고, 다른 사람을 치료할 수는 없어요. 마지막 생명을 잃을 때는 남의 차례에도 즉시 낼 수 있어요.';groups['회복하기'].push(hhOption('birra',status,body));if(h.alive>2&&!full)sequence.push('생명이 줄었다면 맥주로 회복할 수 있어요. 최대 생명과 남은 사람 수를 먼저 확인하세요.');}
 if(hhCount('saloon'))groups['회복하기'].push(hhOption('saloon','모두 생명 1 회복','내 차례에 쓰고 버리면 <strong>나를 포함한 모든 생존자</strong>가 최대 생명까지 1씩 회복해요. 다른 편도 회복하므로 사용 여부를 골라요. 마지막 생명을 잃는 순간에는 대신 낼 수 없어요.'));
 const weapons=calcWeapons.filter(([id])=>id!=='colt'&&hhCount(id));
 for(const [id,name,r] of weapons){groups['장비 놓기'].push(hhOption(id,h.weapon===id?'이미 같은 무기를 놓았어요':`놓으면 사거리 ${r}`,h.weapon===id?'같은 무기는 내 앞에 중복해서 놓을 수 없어요.':`손에서 내 앞에 앞면으로 놓아요. 기존 무기는 버려요. <strong>무기를 놓는 것만으로 공격하지 않아요.</strong> ${id==='volcanic'?'사거리는 1이며, 손의 뱅!을 여러 장 쓸 수 있어요.':'이후 뱅!을 쓸 때 거리 '+r+'까지 닿아요.'}`));}
 for(const id of ['barile','mustang','mirino','dinamite'])if(hhCount(id)){const equipped=h.equipped.has(id);const info={barile:'내 앞에 놓아두세요. 이후 뱅!·기관총을 맞을 때 뽑는 더미 맨 위 1장을 뒤집어 ♥(하트)면 막아요. 실패하면 빗나감!을 추가로 낼 수 있어요.',mustang:'내 앞에 놓으면 다른 사람이 나를 1칸 더 멀게 봐요. 내가 공격할 때의 거리는 그대로예요.',mirino:'내 앞에 놓으면 내가 다른 사람을 1칸 가깝게 봐요. 기본 총으로도 원래 거리 2인 사람에게 닿을 수 있어요.',dinamite:'내 앞에 놓아요. 다음 내 차례부터 폭발 여부를 확인해요. ♠(스페이드) 2~9면 내 생명 3을 잃고, 아니면 왼쪽 사람에게 넘겨요. 나도 피해를 받을 수 있으니 꼭 쓸 필요는 없어요.'};groups['장비 놓기'].push(hhOption(id,equipped?'이미 놓음 · 중복 불가':'내 앞에 놓아 효과 유지',equipped?'같은 이름의 장비는 내 앞에 1장만 놓을 수 있어요. 손의 카드는 남겨두거나 차례 끝에 버릴 카드로 골라도 돼요.':info[id]));}
 if(weapons.some(([id])=>id!==h.weapon)||['barile','mustang','mirino'].some(id=>hhCount(id)&&!h.equipped.has(id)))sequence.push('쓰고 싶은 무기·장비를 내 앞에 놓으세요. 무기와 조준경을 놓은 뒤에는 공격할 수 있는 거리가 달라져요.');
 const shots=hhCount('bang')+(janet?hhCount('mancato'):0);
 if(hhCount('bang')){const blocked=h.usedBang&&!unlimited;groups['공격하기'].push(hhOption('bang',blocked?(canEquipVolcanic?'볼캐닉을 먼저 놓으면 추가 사용 가능':'이번 차례에는 추가 사용 불가'):unlimited?'여러 장 사용 가능':'보통 이번 차례에 1장',blocked?(canEquipVolcanic?'손의 볼캐닉을 먼저 내 앞에 놓으면, 사거리 1 안에 뱅!을 더 쓸 수 있어요.':'이미 뱅!을 썼다면 보통 다시 쏠 수 없어요. 남은 뱅!은 다음 차례나 결투·인디언!에 대응할 때 쓸 수 있어요.'):'내 총이 닿는 한 사람을 고르고 뱅!을 내서 중앙에 버려요. 그 사람이 빗나감!으로 막지 못하면 생명 1을 잃어요. 공격이 끝나도 내 차례는 계속돼요.'));}
 if(janet&&hhCount('mancato'))groups['공격하기'].push(hhOption('mancato',h.usedBang&&!unlimited?'이번 차례 뱅! 제한 확인':'자넷: 뱅!처럼 사용 가능','칼라미티 자넷은 빗나감!을 뱅!처럼 쓸 수 있어요. <strong>이렇게 쏘는 것도 차례당 뱅! 1장 제한에 포함</strong>돼요. 방어용으로 남길 수도 있어요.'));
 for(const id of ['gatling','indiani','duello'])if(hhCount(id)){const info={gatling:'나 빼고 모두를 공격해요. 각자 빗나감!·술통으로 막지 못하면 생명 1을 잃어요. 거리와 관계없고 뱅! 1장 제한과도 별개예요.',indiani:'나 빼고 모두가 뱅! 1장을 버리거나 생명 1을 잃어요. <strong>빗나감!·술통으로는 막지 못해요.</strong> 거리와 관계없어요.',duello:'거리와 관계없이 한 명을 고르세요. 그 사람부터 나와 번갈아 손의 뱅!을 버려요. 먼저 못 내거나 포기한 사람이 생명 1을 잃어요. 빗나감!·술통은 쓸 수 없어요. 뱅!이 부족하면 나도 질 수 있어요.'};groups['공격하기'].push(hhOption(id,'내 차례에 사용 · 쓰고 버리기',info[id]));}
 if(shots&&(!h.usedBang||unlimited||canEquipVolcanic))sequence.push('공격하려면 먼저 거리를 확인하고 뱅!을 내세요. 보통 1장만 쓸 수 있고, 꼭 공격해야 하는 것은 아니에요.');
 for(const id of ['panico','catbalou','prigione'])if(hhCount(id)){const info={panico:'거리 1 이내인 사람의 손에서 보지 않고 1장, 또는 그 사람 앞의 카드 중 원하는 1장을 가져와 <strong>내 손에 넣어요.</strong> 무기 사거리가 길어도 강탈!의 거리는 늘지 않아요.',catbalou:'거리와 관계없이 한 사람의 손에서 보지 않고 1장, 또는 앞에 놓인 원하는 1장을 골라 <strong>중앙에 버려요.</strong> 내 손에 가져오는 효과가 아니에요.',prigione:'<strong>보안관을 제외한 다른 사람</strong> 앞에 놓아요. 거리와 관계없어요. 그 사람 앞에 감옥이 이미 있다면 또 놓을 수 없어요. 그 사람은 자기 차례 시작에 ♥(하트)가 아니면 한 차례 쉬어요.'};groups['다른 사람 방해하기'].push(hhOption(id,id==='prigione'?'고른 사람 앞에 놓기':'내 차례에 사용 · 쓰고 버리기',info[id]));}
 if(hhCount('mancato'))groups['공격받을 때 남겨두기'].push(hhOption('mancato',janet?'방어 또는 자넷의 공격에 사용':'지금 혼자 내는 카드가 아니에요','나에게 뱅!·기관총이 왔을 때 1장 내서 막고 버려요. <strong>내 차례가 아니어도 공격받으면 낼 수 있어요.</strong> 인디언!·결투에는 쓸 수 없어요.'));
 if(h.character==='sidketchum')groups['회복하기'].push(`<article class="hh-ability"><h4>시드 케첨의 능력</h4><p>${full?'현재 생명이 이미 최대라서 지금은 회복할 수 없어요.':hhTotal()>=2?'손의 카드 2장을 골라 버리고 생명 1을 회복할 수 있어요. 최대 생명을 넘기지는 못해요. 2명만 남아도 가능해요.':'회복하려면 손의 카드가 최소 2장 필요해요.'}</p></article>`);
 sequence.push('더 쓸 카드가 없거나 쓰고 싶지 않으면, 현재 생명 수만큼 손에 남기고 초과 카드를 골라 버리세요.');
 openModal(`<section class="hand-helper hh-results"><h2>고른 카드로 할 수 있는 일</h2><p class="hh-lead">손에 ${hhTotal()}장 선택했어요. 아래에서 <strong>쓰고 싶은 카드만</strong> 골라 사용하면 돼요.</p><button class="btn secondary" data-hh-back>카드·내 상황 다시 고르기</button><details class="hh-order"><summary>무엇부터 할지 모르겠다면</summary><ol>${sequence.map(t=>`<li>${t}</li>`).join('')}</ol><p>정해진 순서는 아니에요. 실제로 카드를 쓰거나 새로 뽑으면 선택한 카드와 상태를 다시 맞춰주세요.</p></details>${char?`<details class="hh-character"><summary>내 캐릭터: ${char.name}</summary><p>${char.text}</p><p>캐릭터의 예외 능력을 함께 적용하세요.</p></details>`:''}${Object.entries(groups).filter(([,items])=>items.length).map(([title,items])=>`<section class="hh-group"><h3>${title}</h3>${items.join('')}</section>`).join('')}<div class="callout">공격할 사람은 내 역할의 목표에 맞춰 고르세요. <strong>역할은 보안관 외에는 비밀이에요.</strong> 거리·상대의 방어 카드·캐릭터 능력도 확인하세요.</div><div class="hh-finish"><button class="btn secondary" data-hh-back>카드 다시 고르기</button><button class="btn" data-hh-done>확인했어요</button></div></section>`);
}
document.addEventListener('click',e=>{
 if(e.target.closest('[data-hand-helper]')||e.target.closest('[data-hh-back]')){hhOpen();return}
 const plus=e.target.closest('[data-hh-plus]'),minus=e.target.closest('[data-hh-minus]'),tab=e.target.closest('[data-hh-tab]');
 if(plus||minus){const id=plus?plus.dataset.hhPlus:minus.dataset.hhMinus;hhState.hand[id]=Math.max(0,hhCount(id)+(plus?1:-1));$('#hh-picker').innerHTML=hhPicker();hhSelected();return}
 if(tab){hhState.tab=tab.dataset.hhTab;document.querySelectorAll('[data-hh-tab]').forEach(b=>{b.classList.toggle('on',b.dataset.hhTab===hhState.tab);b.setAttribute('aria-pressed',String(b.dataset.hhTab===hhState.tab))});$('#hh-picker').innerHTML=hhPicker();return}
 if(e.target.closest('#hh-explain'))hhResults();
 if(e.target.closest('[data-hh-done]'))modal.close();
});
document.addEventListener('change',e=>{const map={'hh-hp':'hp','hh-max':'max','hh-character':'character','hh-weapon':'weapon'};if(map[e.target.id])hhState[map[e.target.id]]=e.target.value;if(e.target.id==='hh-alive')hhState.alive=Number(e.target.value);if(e.target.id==='hh-used-bang')hhState.usedBang=e.target.checked;if(e.target.matches('[data-hh-equipped]')){const id=e.target.dataset.hhEquipped;if(e.target.checked)hhState.equipped.add(id);else hhState.equipped.delete(id)}});
